<template>
 <section class="interleaved-panel" aria-label="交错练习" :aria-busy="busy||loading"><h2>交错练习</h2><p>手动确认两个不同知识专题各自对应的已保存私人题版，交替抽取各2–3题。该身份关联只用于本次会话，不更新掌握度。题版预览过，因此标记为可能暴露，不宣称首次无提示测验。</p>
 <p v-if="loading" role="status">正在读取可用题版…</p><p v-if="error" role="alert">{{error}} <Button :disabled="busy" @click="load">重试</Button></p>
 <template v-if="pool"><p>实际可用私人题版：{{pool.quizzes.length}}。每个已保存题版最多取3题；少于两个题版时不能开始。</p><div v-for="(_topic,i) in topics" :key="i" class="interleaved-topic"><Select v-model="topics[i]!.knowledgeId" :label="`专题${i+1}知识点`" :options="nodes.map(n=>({value:n.id,label:n.name+' #'+n.id}))" :disabled="busy"/><Select v-model="topics[i]!.quizId" :label="`专题${i+1}原题版`" :options="pool.quizzes.map(q=>({value:q.id,label:q.title+' #'+q.id}))" :disabled="busy"/></div><Select v-model="count" label="本次题量" :options="[{value:4,label:'4题（每专题2题）'},{value:6,label:'6题（每专题3题）'}]" :disabled="busy"/><Button :loading="busy" :disabled="!canStart" @click="start">开始交错练习</Button></template>
 <article v-if="session"><h3>会话 #{{session.id}} · {{session.state}}</h3><p>客观判分：原私人测验 ExamGrader · 原题版冻结 · 无会话掌握度加分</p><p v-if="session.state==='SOURCE_UNAVAILABLE'">原来源不可访问，题目和答卷已隐藏。</p><p v-else>知识点分布：{{distribution}}</p><template v-for="(item,i) in session.items" :key="item.attemptId"><p>第{{i+1}}题 · 知识点 #{{item.knowledgeId}} · 原题版 #{{item.quizId}} v{{item.quizVersion}} · {{item.conditions}}</p><template v-if="session.state==='IN_PROGRESS'&&i===position"><h3>{{question(item)?.content}}</h3><label v-for="option in options(item)" :key="option.value" class="interleaved-option"><input v-model="answers[i]" type="radio" :value="option.value" :name="`interleaved-${session.id}-${i}`" :disabled="busy"/>{{option.label}}</label></template><template v-else-if="item.attempt.items"><p>{{item.attempt.items[0]?.question.content}}</p><p>原答：{{item.attempt.items[0]?.userAnswer}} · {{item.attempt.items[0]?.correct?'正确':'错题'}} · 客观得分 {{item.attempt.score}}/100</p><p>{{item.attempt.items[0]?.question.explanation}}</p><RouterLink to="/notes">返回原笔记查看错因与补练</RouterLink></template></template><div v-if="session.state==='IN_PROGRESS'" class="interleaved-actions"><Button :disabled="busy||position===0" @click="position--">上一题</Button><Button v-if="position<session.items.length-1" :disabled="busy||!answers[position]" @click="position++">下一题</Button><Button v-else :loading="busy" :disabled="answers.filter(Boolean).length!==session.items.length" @click="submit">提交交错答卷</Button></div></article>
 <h3>实际练习历史</h3><p v-if="!history.length&&!loading">暂无交错会话。</p><Button v-for="h in history" :key="h.id" variant="ghost" :disabled="busy" @click="open(h.id)">会话 #{{h.id}} · {{h.state}}</Button>
 </section>
</template>
<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {knowledgeApi} from '@/api'
import {interleavedApi,type InterleavedSession,type InterleavedPool} from '@/api/interleavedPractice'
import Button from '@/components/ui/Button.vue'
import Select from '@/components/ui/Select.vue'
const pool=ref<InterleavedPool|null>(null),nodes=ref<{id:number;name:string}[]>([]),topics=ref([{knowledgeId:0,quizId:0},{knowledgeId:0,quizId:0}]),count=ref(4),session=ref<InterleavedSession|null>(null),history=ref<InterleavedSession[]>([]),answers=ref<string[]>([]),position=ref(0),loading=ref(false),busy=ref(false),error=ref('')
const auth=useAuthStore();let epoch=0;onUnmounted(()=>epoch++);const key=ref(crypto.randomUUID())
const canStart=computed(()=>pool.value&&pool.value.quizzes.length>=2&&topics.value.every(t=>t.knowledgeId>0&&t.quizId>0)&&topics.value[0]!.knowledgeId!==topics.value[1]!.knowledgeId&&topics.value[0]!.quizId!==topics.value[1]!.quizId)
const distribution=computed(()=>{const d=new Map<number,number>();session.value?.items.forEach(i=>d.set(i.knowledgeId,(d.get(i.knowledgeId)||0)+1));return [...d].map(([k,n])=>'#'+k+'：'+n+'题').join('，')})
function question(item:InterleavedSession['items'][number]){return item.attempt.questions?.[0]}
function options(item:InterleavedSession['items'][number]){const q=question(item);return q?.type==='TRUE_FALSE'?[{value:'true',label:'正确'},{value:'false',label:'错误'}]:q?.options.map((label,i)=>({value:String(i),label}))||[]}
async function load(){const current=++epoch;loading.value=true;error.value='';try{const [a,b,c]=await Promise.all([interleavedApi.pool(),knowledgeApi.entityGraph(),interleavedApi.history()]);if(current!==epoch)return;pool.value=a;nodes.value=b.nodes;history.value=c}catch(e){if(current===epoch)error.value=e instanceof Error?e.message:'读取失败'}finally{if(current===epoch)loading.value=false}}
async function run(work:()=>Promise<void>){if(busy.value)return;const current=epoch;busy.value=true;error.value='';try{await work()}catch(e){if(current===epoch)error.value=e instanceof Error?e.message:'练习操作失败'}finally{if(current===epoch)busy.value=false}}
function start(){const current=epoch;return run(async()=>{const value=await interleavedApi.start(key.value,topics.value,count.value);if(current!==epoch)return;session.value=value;answers.value=Array(session.value.items.length).fill('');position.value=0;key.value=crypto.randomUUID();const historyValue=await interleavedApi.history();if(current!==epoch)return;history.value=historyValue})}
function open(id:number){const current=epoch;return run(async()=>{const value=await interleavedApi.get(id);if(current!==epoch)return;session.value=value;answers.value=Array(session.value.items.length).fill('');position.value=0})}
function submit(){const current=epoch;return run(async()=>{if(!session.value)return;const value=await interleavedApi.submit(session.value.id,answers.value);if(current!==epoch)return;session.value=value;const historyValue=await interleavedApi.history();if(current!==epoch)return;history.value=historyValue})}
watch(()=>auth.user?.id,()=>{epoch++;pool.value=null;nodes.value=[];history.value=[];session.value=null;answers.value=[];busy.value=false;error.value='';key.value=crypto.randomUUID();void load()},{immediate:true})
</script>
<style scoped>
.interleaved-panel{padding:var(--kf-space-4);margin-block:var(--kf-space-4);background:var(--kf-card);border-radius:var(--kf-radius-md)}.interleaved-topic{display:grid;grid-template-columns:1fr 1fr;gap:var(--kf-space-4);margin-block:var(--kf-space-3)}.interleaved-panel p{margin-block:var(--kf-space-3);overflow-wrap:anywhere}.interleaved-option,.interleaved-actions{display:flex;gap:var(--kf-space-2);align-items:center;margin-block:var(--kf-space-2)}.interleaved-panel article{margin-block:var(--kf-space-4)}@media(max-width:640px){.interleaved-topic{grid-template-columns:1fr}}
</style>
